# Reviewed under AGENTS.md
import csv


def normalize_email(value):
    return (value or '').strip().lower()


def main():
    with open('contacts.csv', newline='', encoding='utf-8-sig') as handle:
        reader = csv.DictReader(handle)
        rows = list(reader)

    best = {}
    for position, row in enumerate(rows):
        email = normalize_email(row.get('email'))
        created = (row.get('created') or '').strip()
        name = (row.get('name') or '').strip()
        candidate = (created, position, name, email)
        current = best.get(email)
        if current is None or created < current[0]:
            best[email] = candidate

    ordered = sorted(best.values(), key=lambda item: (item[0], item[3]))

    with open('clean.csv', 'w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['name', 'email', 'created'])
        for created, _position, name, email in ordered:
            writer.writerow([name, email, created])


if __name__ == '__main__':
    main()
